    std::uint64_t *aWUSaltB = pDomainSaltSet->mWandererUpdate.mSaltB;
    std::uint64_t *aWUSaltC = pDomainSaltSet->mWandererUpdate.mSaltC;
    std::uint64_t *aWUSaltD = pDomainSaltSet->mWandererUpdate.mSaltD;
    std::uint64_t *aWUSaltE = pDomainSaltSet->mWandererUpdate.mSaltE;
    std::uint64_t *aWUSaltF = pDomainSaltSet->mWandererUpdate.mSaltF;
    std::uint64_t *aWUSaltG = pDomainSaltSet->mWandererUpdate.mSaltG;
    std::uint64_t *aWUSaltH = pDomainSaltSet->mWandererUpdate.mSaltH;
    std::uint8_t *aFireLaneA = pWorkSpace->mFireLaneA;
    std::uint8_t *aFireLaneB = pWorkSpace->mFireLaneB;
    std::uint8_t *aEarthLaneA = pWorkSpace->mEarthLaneA;
    std::uint8_t *aEarthLaneB = pWorkSpace->mEarthLaneB;
    std::uint8_t *aEarthLaneC = pWorkSpace->mEarthLaneC;
    std::uint8_t *aEarthLaneD = pWorkSpace->mEarthLaneD;
    std::uint64_t aCross = 0; std::uint64_t aScatter = 0;

    std::uint64_t aOrbiterA = 0; std::uint64_t aOrbiterB = 0; std::uint64_t aOrbiterC = 0; std::uint64_t aOrbiterD = 0;
    std::uint64_t aOrbiterE = 0; std::uint64_t aOrbiterF = 0; std::uint64_t aOrbiterG = 0; std::uint64_t aOrbiterH = 0;
    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [kdf-a arx]
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseB(pNonce * 0xE7AA6FD98D9AF45DULL + 0xE97F98E380D4A353ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseB(pNonce * 0x98E1D6A6037A7E03ULL + 0x973E05439A9D81B0ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordC = TwistMix64::DiffuseA(pNonce * 0xB8B0455C449417C9ULL + 0x8095343F5BAE8475ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordD = TwistMix64::DiffuseA(pNonce * 0xC0D28AB3F99B8597ULL + 0xB214AA9EAFF0B0E0ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordE = TwistMix64::DiffuseC(pNonce * 0xFE140A06078B1AF1ULL + 0xC45269A52F003223ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordF = TwistMix64::DiffuseC(pNonce * 0xCD95BC14C4E2D7FFULL + 0x817C93EF1D144B4EULL);
    [[maybe_unused]] const std::uint64_t aNonceWordG = TwistMix64::DiffuseB(pNonce * 0xB7A183C0A05E0B45ULL + 0xFCE487D1BE17E2C8ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordH = TwistMix64::DiffuseB(pNonce * 0xA4465FE6660E419FULL + 0x848E5AC2670047E4ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordI = TwistMix64::DiffuseC(pNonce * 0x84B11EB55BEE2BD1ULL + 0xE3532AEA1A64B0D4ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordJ = TwistMix64::DiffuseB(pNonce * 0xF04BE787DE8DA91FULL + 0x8F58A970BD1053F7ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordK = TwistMix64::DiffuseB(pNonce * 0xEE49D9EC18F0494BULL + 0xCFD89909F94D639FULL);
    [[maybe_unused]] const std::uint64_t aNonceWordL = TwistMix64::DiffuseB(pNonce * 0x88FED8C9E46FB387ULL + 0xC1014FA143E687A8ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordM = TwistMix64::DiffuseA(pNonce * 0xE5663BB1FF6D43F5ULL + 0xE1D84F6C88181A59ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordN = TwistMix64::DiffuseC(pNonce * 0xE45A91A2E0E7A851ULL + 0xDBD842D1BE3C35ADULL);
    [[maybe_unused]] const std::uint64_t aNonceWordO = TwistMix64::DiffuseA(pNonce * 0xB16CAEE437D89B35ULL + 0xC39643D4787EADE3ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordP = TwistMix64::DiffuseC(pNonce * 0xBB872A8F0AA6EABFULL + 0xF26FC63EDA1D6E6CULL);
    std::uint64_t aDomainWordIngress = pConstants->mIngress;
