            aOrbiterG = (((aWandererD + RotL64(aIngress, 12U)) + RotL64(aCarry, 21U)) + 0x9B86E71F5859BD94ULL) + aOASaltB[((aIndex + 384U)) & S_SALT1];
            aOrbiterK = ((aWandererA + RotL64(aScatter, 47U)) + RotL64(aCarry, 43U)) + 0xFC25BF69D040A234ULL;
            aOrbiterD = (aWandererH + RotL64(aCross, 5U)) + 0x32F90AB487F37194ULL;
