            aCross ^= (RotL64(pCrossLaneB[((S_BLOCK1 - aIndex + 13315U)) & S_BLOCK1], 22U) ^ RotL64(aFireLaneA[((aIndex + 15558U)) & S_BLOCK1], 57U));
            aCross = TwistMix64::DiffuseB((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aCross, 53U) + RotL64(aPrevious, 4U)) + (RotL64(aIngress, 23U) ^ RotL64(aCarry, 39U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterI = ((aWandererF + RotL64(aPrevious, 13U)) + RotL64(aCarry, 53U)) + 0x734CCC80C97B7F54ULL;
            aOrbiterC = ((aWandererA + RotL64(aCross, 6U)) + RotL64(aCarry, 11U)) + 0xD4A98EA290FCF3A1ULL;
            aOrbiterJ = ((aWandererE + RotL64(aScatter, 21U)) + 0xE608EED5784B4AAAULL) + aOASaltD[(((511U - aIndex) + 495U)) & S_SALT1];
